from playwright.sync_api import sync_playwright,expect
from play_qa_support import AppServer,Report,browser,timed_page,advance,snapshot,upgrade_and_offline,enable_survival,enter_lab,unlock_all
server=AppServer();report=Report('v2-building-qa')
with sync_playwright() as p:
 b=browser(p);c,pg=timed_page(b,server,report);enable_survival(pg);unlock_all(pg);pg.locator('#constructionDetails>summary').click();expect(pg.locator('#buildImage')).to_have_attribute('src','assets/concepts/v2/07_hangar_expansion_module.webp');pg.locator('#buildImage').evaluate('im=>im.decode()');assert '/07_' in pg.locator('#buildImage').get_attribute('src');before=snapshot(pg);pg.locator('[data-build-slot=greenhouse]').select_option('engine-port');pg.locator('[data-build=greenhouse]').click();expect(pg.locator('#buildMessage')).to_contain_text('위치');assert snapshot(pg)==before
 pg.locator('[data-build-slot=greenhouse]').select_option('garden-port');pg.locator('[data-build=greenhouse]').click();s=snapshot(pg);assert s['progress']['materials']==before['progress']['materials']-8;assert s['resources']['amounts']['power']==before['resources']['amounts']['power']-8;expect(pg.locator('[data-build=greenhouse]')).to_be_disabled();pg.locator('[data-build=recycler]').click();assert len(snapshot(pg)['modules']['installed'])==2;report.passed('actual missions -> all three research unlocks -> two facilities; wrong slot atomic, printed costs charged once')
 pg.locator('[data-panel=home]').click();expect(pg.locator('#mapFacilities [data-facility]')).to_have_count(2);expect(pg.locator('#resourceRows')).to_contain_text('0.50');stock=snapshot(pg)['resources']['amounts']['food'];advance(pg,6);assert snapshot(pg)['resources']['amounts']['food']>stock;pg.locator('#cutawayViewBtn').click();expect(pg.locator('#cutawayFacilities [data-facility]')).to_have_count(2);pg.locator('#exteriorViewBtn').click();expect(pg.locator('#exteriorFacilities [data-facility]')).to_have_count(2);report.passed('real production changes food; shared inventory table and map/cutaway/exterior show two installed game facilities')
 enter_lab(pg);before=snapshot(pg);pg.locator('[data-remove=greenhouse]').click();assert snapshot(pg)['progress']['materials']==before['progress']['materials']+4;assert 'greenhouse' not in snapshot(pg)['modules']['installed'];expect(pg.locator('[data-remove=greenhouse]')).to_be_disabled();pg.locator('#buildCards .game-card').nth(1).get_by_role('button',name='설비 그림 보기').click();pg.locator('#buildImage').evaluate('im=>im.decode()');assert '/08_' in pg.locator('#buildImage').get_attribute('src');pg.locator('#explorationPanel').screenshot(path=str(report.out/'desktop-building.png'));c.close();report.passed('teardown refunds 50% materials once; recycler scene uses 08; base rooms remain')
 for w,h in [(768,1024),(390,844)]:
  c,m=timed_page(b,server,report,w,h);enable_survival(m);unlock_all(m);m.locator('#constructionDetails>summary').tap();m.locator('[data-build=greenhouse]').tap();assert 'greenhouse' in snapshot(m)['modules']['installed'];assert m.evaluate('document.documentElement.scrollWidth<=innerWidth');m.locator('#constructionDetails').screenshot(path=str(report.out/f'building-{w}.png'));c.close()
 report.passed('tablet/mobile real progression and installation, accessible selects/buttons and no overflow (emulated)')
 c,o=upgrade_and_offline(b,server,report);enable_survival(o);enter_lab(o);o.locator('#constructionDetails>summary').click();expect(o.locator('[data-build=greenhouse]')).to_be_visible();o.locator('[data-build=greenhouse]').click();expect(o.locator('#buildMessage')).to_contain_text('연구');c.close();report.passed('offline construction code and prerequisite error survive optional-image absence')
 b.close()
report.finish();server.close()
